body.raw:
{
  "_comment": "Do these in SAP GUI. Nothing here is callable.",
  "1_stock_in_transit_BEFORE_posting": {
    "tcode": "MB5T",
    "purpose": "Confirms a goods issue (641) has posted and stock is sitting in transit at the receiving plant. Without this the receipt will correctly fail.",
    "alternative": "ME23N > select item > Purchase Order History tab > look for VGABE=6 / BEWTP=U with movement 641"
  },
  "2_open_goods_receipt_quantity": {
    "tcode": "ME23N",
    "path": "select the item > Schedule lines tab",
    "table": "EKET",
    "rule": "MENGE (scheduled) must be greater than WEMNG (already received). If they are equal the item is fully received and cannot be posted again.",
    "proven": "5600084239/00010 moved from WEMNG 0.000 to 2.000 after the certified call"
  },
  "3_the_document_flow_after_posting": {
    "tcode": "ME23N",
    "path": "select the item > Purchase Order History tab",
    "table": "EKBE",
    "expect": "a new row VGABE=1 / BEWTP=E with movement 101, your quantity, today's date and your user",
    "proven_example": "VGABE=1 BEWTP=E BELNR=5007138597/2026 BWART=101 qty 2.000 25.08.2026 12:41 QNOVATE8",
    "note": "For stock transport orders EKBE is the document flow. VBFA is the SD flow and is correctly EMPTY for a PO-to-delivery link, because a purchase order has no SD document category."
  },
  "4_the_material_document_itself": {
    "tcode": "MB03",
    "input": "material document number + year",
    "tables": "MKPF header, MSEG items",
    "expect": "BWART 101, MATNR, WERKS, LGORT, MENGE/MEINS, EBELN/EBELP matching what you sent, SHKZG = S",
    "also": "MB51 lists material documents by material, plant, movement type and date; MMBE and MB52 show resulting stock"
  },
  "_se16_warning": "Selection-screen field IDs in SE16 are POSITIONAL and differ per table. ctxtI4-LOW is BWART on MSEG and something else elsewhere. Always run a positive control - a filter value you know returns rows - before trusting a 'no entries found'.",
  "_open_item_for_MM": "On the certified posting, EKBE shows the goods issue valued at 10,867.50 INR and the goods receipt at 0.00, and MSEG-DMBTR is likewise 0.00. For a stock transfer the receiving value normally derives from the issuing plant. This is NOT established as correct or incorrect and needs an MM answer before any value field is put into an external contract."
}
